package com.pixarch.app.core.clip

import ai.onnxruntime.OnnxTensor
import ai.onnxruntime.OrtEnvironment
import ai.onnxruntime.OrtSession
import android.content.Context
import android.graphics.Bitmap
import java.io.File
import java.io.FileOutputStream
import java.nio.FloatBuffer
import java.nio.LongBuffer
import kotlin.math.sqrt

/**
 * On-device ONNX Runtime wrapper for the MobileCLIP2-S0 INT8 encoders.
 *
 * The model files are generated by `scripts/export_edge_models.py`, which also applies
 * the ArgMax int32 patch the text encoder needs on Android (ORT mobile has no int64
 * ArgMax kernel). They are gitignored; the `checkEdgeModels` Gradle task fails the
 * build with instructions when they are missing.
 */
class OnnxClipRunner(
    private val context: Context,
    private val visualModelAsset: String = "models/mobileclip_visual_int8.onnx",
    private val textModelAsset: String = "models/mobileclip_text_int8.onnx",
    val imageSize: Int = ClipPreprocess.IMAGE_SIZE
) : AutoCloseable {

    private val env: OrtEnvironment = OrtEnvironment.getEnvironment()
    private val visualSession: OrtSession = createSession(visualModelAsset, "mobileclip_visual.onnx")
    private var textSession: OrtSession? = null

    private fun sessionOptions() = OrtSession.SessionOptions().apply {
        setOptimizationLevel(OrtSession.SessionOptions.OptLevel.ALL_OPT)
        setIntraOpNumThreads(2)
    }

    private fun createSession(assetPath: String, cacheName: String): OrtSession {
        val file = copyAssetToCache(assetPath, cacheName)
        return env.createSession(file.absolutePath, sessionOptions())
    }

    /** The text encoder (~64 MB) is only loaded the first time a query needs it. */
    @Synchronized
    private fun getTextSession(): OrtSession =
        textSession ?: createSession(textModelAsset, "mobileclip_text.onnx").also { textSession = it }

    private fun copyAssetToCache(assetPath: String, cacheName: String): File {
        val target = File(context.cacheDir, cacheName)
        val assetLength = try {
            context.assets.openFd(assetPath).use { it.length }
        } catch (e: java.io.FileNotFoundException) {
            throw IllegalStateException(
                "Missing model asset '$assetPath'. Run: python scripts/export_edge_models.py", e
            )
        }
        if (!target.exists() || target.length() != assetLength) {
            val tmp = File(context.cacheDir, "$cacheName.tmp")
            context.assets.open(assetPath).use { input ->
                FileOutputStream(tmp).use { output -> input.copyTo(output) }
            }
            check(tmp.renameTo(target) || (target.delete() && tmp.renameTo(target))) {
                "Could not move $tmp to $target"
            }
        }
        return target
    }

    private fun normalizeL2(vec: FloatArray): FloatArray {
        var normSq = 0f
        for (v in vec) normSq += v * v
        val norm = sqrt(maxOf(normSq, 1e-12f))
        for (i in vec.indices) vec[i] /= norm
        return vec
    }

    /** Errors propagate: a zero vector here would silently rank every image as 0.0. */
    fun encodeText(tokens: LongArray): FloatArray {
        val session = getTextSession()
        val shape = longArrayOf(1, tokens.size.toLong())
        OnnxTensor.createTensor(env, LongBuffer.wrap(tokens), shape).use { tensor ->
            session.run(mapOf("text" to tensor)).use { result ->
                @Suppress("UNCHECKED_CAST")
                val output = result[0].value as Array<FloatArray>
                return normalizeL2(output[0].clone())
            }
        }
    }

    fun encodeImage(bitmap: Bitmap): FloatArray {
        val input = ClipPreprocess.resizeAndCrop(bitmap, imageSize)
        val pixels = IntArray(imageSize * imageSize)
        input.getPixels(pixels, 0, imageSize, 0, 0, imageSize, imageSize)
        if (input !== bitmap) input.recycle()

        val chw = ClipPreprocess.toChw(pixels, imageSize)
        val shape = longArrayOf(1, 3, imageSize.toLong(), imageSize.toLong())
        OnnxTensor.createTensor(env, FloatBuffer.wrap(chw), shape).use { tensor ->
            visualSession.run(mapOf("image" to tensor)).use { result ->
                @Suppress("UNCHECKED_CAST")
                val output = result[0].value as Array<FloatArray>
                return normalizeL2(output[0].clone())
            }
        }
    }

    override fun close() {
        visualSession.close()
        textSession?.close()
    }
}
